USE [DeineDatenbank];
GO
-- Synthetic pipeline phase-begin reports; no SSIS package or provider execution.
DECLARE @OuterOptions int=@@OPTIONS,@OuterLock int=@@LOCK_TIMEOUT,@OuterTran int=@@TRANCOUNT;
DECLARE @TableId int=NULL,@UserId int=NULL,@Impersonated bit=0,@Db sysname=DB_NAME();
IF OBJECT_ID(N'dbo.ExamplePipelinePhaseBeginLogSource') IS NOT NULL OR DATABASE_PRINCIPAL_ID(N'ExamplePipelinePhaseBeginReader') IS NOT NULL THROW 57190,N'PB_FIXTURE_COLLISION',1;
BEGIN TRY
    CREATE TABLE dbo.ExamplePipelinePhaseBeginLogSource(id int NOT NULL,event nvarchar(128) COLLATE SQL_Latin1_General_CP1_CS_AS NULL,source nvarchar(128) COLLATE SQL_Latin1_General_CP1_CS_AS NULL,sourceid uniqueidentifier NULL,executionid uniqueidentifier NOT NULL,starttime datetime NULL,endtime datetime NULL,datacode int NULL,message nvarchar(max) COLLATE SQL_Latin1_General_CP1_CS_AS NULL);
    SET @TableId=OBJECT_ID(N'dbo.ExamplePipelinePhaseBeginLogSource');
    DECLARE @Id uniqueidentifier=N'00000000-0000-0000-0000-000000000001',@J nvarchar(max),@Status varchar(40),@Error int,@Message nvarchar(4000),
        @F int=0,@Task bit,@Row bit,@Phase bit,@Life bit,@Lookup bit,@Written bit,@Through bit,@Final bit,@Begin bit;
    WHILE @F<256
    BEGIN
        SELECT @Task=CONVERT(bit,@F&1),@Row=CONVERT(bit,@F&2),@Phase=CONVERT(bit,@F&4),@Life=CONVERT(bit,@F&8),@Lookup=CONVERT(bit,@F&16),@Written=CONVERT(bit,@F&32),@Through=CONVERT(bit,@F&64),@Final=CONVERT(bit,@F&128);
        EXEC [monitor].[USP_SsisLegacyLogAnalysis] @LoggingDatabase=@Db,@LoggingTable=N'ExamplePipelinePhaseBeginLogSource',@ExecutionId=@Id,@HighImpactConfirmed=1,
            @IncludeTaskAnalysis=@Task,@IncludeRowFlowAnalysis=@Row,@IncludeComponentPhaseAnalysis=@Phase,@IncludeComponentLifecyclePhases=@Life,@IncludeLookupCacheAnalysis=@Lookup,@IncludeRowsWrittenAnalysis=@Written,@IncludeThroughputAnalysis=@Through,@IncludeFinalCommitAnalysis=@Final,@IncludePipelinePhaseBeginAnalysis=1,
            @ResultSetArt='NONE',@JsonErzeugen=1,@Json=@J OUTPUT,@PrintMeldungen=0,@StatusCodeOut=@Status OUTPUT;
        IF TRY_CONVERT(int,JSON_VALUE(@J,'$.meta.SchemaVersion'))<>10 OR ISNULL(JSON_QUERY(@J,'$.pipelinePhaseBeginEvents'),N'MISSING')<>N'[]' OR ISNULL(JSON_VALUE(@J,'$.meta.PipelinePhaseBeginCatalogVersion'),N'MISSING')<>N'1' THROW 57101,N'PB_FLAG_VERSION_ARRAY',1;
        IF (((@Life=1 AND @Phase=0) OR (@Through=1 AND @Row=0)) AND @Status<>'INVALID_PARAMETER') OR ((@Life=0 OR @Phase=1) AND (@Through=0 OR @Row=1) AND @Status='INVALID_PARAMETER') THROW 57102,N'PB_FLAG_DEPENDENCY',1;
        SET @F+=1;
    END;
    SET @F=0;
    WHILE @F<2
    BEGIN
        SET @Begin=CASE WHEN @F=0 THEN 0 ELSE NULL END;
        EXEC [monitor].[USP_SsisLegacyLogAnalysis] @LoggingDatabase=@Db,@LoggingTable=N'ExamplePipelinePhaseBeginLogSource',@ExecutionId=@Id,@HighImpactConfirmed=1,@IncludePipelinePhaseBeginAnalysis=@Begin,@IncludeFinalCommitAnalysis=1,@IncludeRowFlowAnalysis=1,@IncludeThroughputAnalysis=1,@ResultSetArt='NONE',@JsonErzeugen=1,@Json=@J OUTPUT,@PrintMeldungen=0;
        IF JSON_VALUE(@J,'$.meta.SchemaVersion')<>N'9' OR JSON_QUERY(@J,'$.pipelinePhaseBeginEvents') IS NOT NULL OR JSON_VALUE(@J,'$.meta.PipelinePhaseBeginCatalogVersion') IS NOT NULL OR EXISTS(SELECT 1 FROM OPENJSON(@J,'$.sourceStatus') WHERE JSON_VALUE(value,'$.SourceOrdinal')=N'12') THROW 57103,N'PB_OPTOUT',1;
        SET @F+=1;
    END;
    CREATE TABLE #ExampleBeginCases(CaseId int,Label varchar(40),Cap int,InputJson nvarchar(max),ExpectedJson nvarchar(max),Candidates int,Parsed int,Assigned int,Limited bit);
