        INSERT #ExampleBeginActual SELECT [PipelinePhaseBeginEventOrdinal], [LogId], [ExecutionId], [EventName], [SourceId], [SourceName], [EventTime], [DataCode], [ParserId], [ParseStatus], [ObservationKind], [PhaseName], [ContextStatus], [ContextStartLogId], [ContextEndLogId], [InputIsTruncated], [EvidenceLevel], [EvidenceSource], [MessageText] FROM OPENJSON(@J,'$.pipelinePhaseBeginEvents') WITH([PipelinePhaseBeginEventOrdinal] bigint '$.PipelinePhaseBeginEventOrdinal', [LogId] int '$.LogId', [ExecutionId] uniqueidentifier '$.ExecutionId', [EventName] nvarchar(128) '$.EventName', [SourceId] uniqueidentifier '$.SourceId', [SourceName] nvarchar(4000) '$.SourceName', [EventTime] datetime '$.EventTime', [DataCode] int '$.DataCode', [ParserId] varchar(32) '$.ParserId', [ParseStatus] varchar(40) '$.ParseStatus', [ObservationKind] varchar(40) '$.ObservationKind', [PhaseName] varchar(32) '$.PhaseName', [ContextStatus] varchar(40) '$.ContextStatus', [ContextStartLogId] int '$.ContextStartLogId', [ContextEndLogId] int '$.ContextEndLogId', [InputIsTruncated] bit '$.InputIsTruncated', [EvidenceLevel] varchar(32) '$.EvidenceLevel', [EvidenceSource] nvarchar(160) '$.EvidenceSource', [MessageText] nvarchar(max) '$.MessageText');
