S [ExecutionId], CONVERT(varbinary(max),[EventName]) AS [EventName], [SourceId] AS [SourceId], CONVERT(varbinary(max),[SourceName]) AS [SourceName], [EventTime] AS [EventTime], [DataCode] AS [DataCode], CONVERT(varbinary(max),[ParserId]) AS [ParserId], CONVERT(varbinary(max),[ParseStatus]) AS [ParseStatus], CONVERT(varbinary(max),[ObservationKind]) AS [ObservationKind], CONVERT(varbinary(max),[PhaseName]) AS [PhaseName], CONVERT(varbinary(max),[ContextStatus]) AS [ContextStatus], [ContextStartLogId] AS [ContextStartLogId], [ContextEndLogId] AS [ContextEndLogId], [InputIsTruncated] AS [InputIsTruncated], CONVERT(varbinary(max),[EvidenceLevel]) AS [EvidenceLevel], CONVERT(varbinary(max),[EvidenceSource]) AS [EvidenceSource], CONVERT(varbinary(max),[MessageText]) AS [MessageText] FROM #ExampleBeginActual EXCEPT SELECT [PipelinePhaseBeginEventOrdinal] AS [PipelinePhaseBeginEventOrdinal], [LogId] AS [LogId], [ExecutionId] AS [ExecutionId], CONVERT(varbinary(max),[EventName]) AS [EventName], [SourceId] AS [SourceId], CONVERT(varbinary(max),[SourceName]) AS [SourceName], [EventTime] AS [EventTime], [DataCode] AS [DataCode], CONVERT(varbinary(max),[ParserId]) AS [ParserId], CONVERT(varbinary(max),[ParseStatus]) AS [ParseStatus], CONVERT(varbinary(max),[ObservationKind]) AS [ObservationKind], CONVERT(varbinary(max),[PhaseName]) AS [PhaseName], CONVERT(varbinary(max),[ContextStatus]) AS [ContextStatus], [ContextStartLogId] AS [ContextStartLogId], [ContextEndLogId] AS [ContextEndLogId], [InputIsTruncated] AS [InputIsTruncated], CONVERT(varbinary(max),[EvidenceLevel]) AS [EvidenceLevel], CONVERT(varbinary(max),[EvidenceSource]) AS [EvidenceSource], CONVERT(varbinary(max),[MessageText]) AS [MessageText] FROM #ExampleBeginExpected)
            OR (SELECT COUNT(*) FROM #ExampleBeginActual)<>@C OR EXISTS(SELECT 1 FROM OPENJSON(@J,'$.pipelinePhaseBeginEvents') r WHERE (SELECT COUNT(*) FROM OPENJSON(r.value))<>19)
        BEGIN SELECT @Case AS FailedCase,@Label AS FailedLabel,@J AS FailedJson;THROW 57105,N'PB_INDEPENDENT_ALL19',1;END;
        IF NOT EXISTS(SELECT 1 FROM OPENJSON(@J,'$.sourceStatus') WHERE JSON_VALUE(value,'$.SourceOrdinal')=N'12' AND JSON_VALUE(value,'$.SourceName')=N'pipelinePhaseBeginAnalysis' AND JSON_VALUE(value,'$.StatusCode')=CASE WHEN @Limited=1 THEN 'AVAILABLE_LIMITED' WHEN @C=0 THEN 'AVAILABLE_EMPTY' ELSE 'AVAILABLE' END AND JSON_VALUE(value,'$.Detail')=N'Candidates='+CONVERT(nvarchar(20),@C)+N';Parsed='+CONVERT(nvarchar(20),@P)+N';ContextAssigned='+CONVERT(nvarchar(20),@A)) THROW 57106,N'PB_SPARSE_COUNTERS',1;
        SET @Case+=1;
    END;
    CREATE TABLE #ExampleBeginExport(Seed int NULL);
    EXEC [monitor].[USP_SsisLegacyLogAnalysis] @LoggingDatabase=@Db,@LoggingTable=N'ExamplePipelinePhaseBeginLogSource',@ExecutionId=@Id,@HighImpactConfirmed=1,@IncludePipelinePhaseBeginAnalysis=1,@ResultSetArt='TABLE',@ResultTablesJson=N'{"pipelinePhaseBeginEvents":"#ExampleBeginExport"}',@JsonErzeugen=1,@Json=@J OUTPUT,@PrintMeldungen=0;
    DECLARE @ExportMatches bit=0;
    EXEC sys.sp_executesql N'SET @Ok=CASE WHEN NOT EXISTS(SELECT [PipelinePhaseBeginEventOrdinal] AS [PipelinePhaseBeginEventOrdinal], [LogId] AS [LogId], [ExecutionId] AS [ExecutionId], CONVERT(varbinary(max),[EventName]) AS [EventName], [SourceId] AS [SourceId], CONVERT(varbinary(max),[SourceName]) AS [SourceName], [EventTime] AS [EventTime], [DataCode] AS [DataCode], CONVERT(varbinary(max),[ParserId]) AS [ParserId], CONVERT(varbinary(max),[ParseStatus]) AS [ParseStatus], CONVERT(varbinary(max),[ObservationKind]) AS [ObservationKind], CONVERT(varbinary(max),[PhaseName]) AS [PhaseName], CONVERT(varbinary(max),[ContextStatus]) AS [ContextStatus], [ContextStartLogId] AS [ContextStartLogId], [ContextEndLogId] AS [ContextEndLogId], [InputIsTruncated] AS [InputIsTruncated], CONVERT(varbinary(max),[EvidenceLevel]) AS [EvidenceLevel], CONVERT(varbinary(max),[EvidenceSource]) AS [EvidenceSource], CONVERT(varbinary(max),[MessageText]) AS [MessageText] FROM #ExampleBeginExport EXCEPT SELECT [PipelinePhaseBeginEventOrdinal] AS [PipelinePhaseBeginEventOrdinal], [LogId] AS [LogId], [ExecutionId] AS [ExecutionId], CONVERT(varbinary(max),[EventName]) AS [EventName], [SourceId] AS [SourceId], CONVERT(varbinary(max),[SourceName]) AS [SourceName], [EventTime] AS [EventTime], [DataCode] AS [DataCode], CONVERT(varbinary(max),[ParserId]) AS [ParserId], CONVERT(varbinary(max),[ParseStatus]) AS [ParseStatus], CONVERT(varbinary(max),[ObservationKind]) AS [ObservationKind], CONVERT(varbinary(max),[PhaseName]) AS [PhaseName], CONVERT(varbinary(max),[ContextStatus]) AS [ContextStatus], [ContextStartLogId] AS [ContextStartLogId], [ContextEndLogId] AS [ContextEndLogId], [InputIsTruncated] AS [InputIsTruncated], CONVERT(varbinary(max),[EvidenceLevel]) AS [EvidenceLevel], CONVERT(varbinary(max),[EvidenceSource]) AS [EvidenceSource], CONVERT(varbinary(max),[MessageText]) AS [MessageText] FROM #ExampleBeginExpected) AND NOT EXISTS(SELECT [PipelinePhaseBeginEventOrdinal] AS [PipelinePhaseBeginEventOrdinal], [LogId] AS [LogId], [ExecutionId] AS [ExecutionId], CONVERT(varbinary(max),[EventName]) AS [EventName], [SourceId] AS [SourceId], CONVERT(varbinary(max),[SourceName]) AS [SourceName], [EventTime] AS [EventTime], [DataCode] AS [DataCode], CONVERT(varbinary(max),[ParserId]) AS [ParserId], CONVERT(varbinary(max),[ParseStatus]) AS [ParseStatus], CONVERT(varbinary(max),[ObservationKind]) AS [ObservationKind], CONVERT(varbinary(max),[PhaseName]) AS [PhaseName], CONVERT(varbinary(max),[ContextStatus]) AS [ContextStatus], [ContextStartLogId] AS [ContextStartLogId], [ContextEndLogId] AS [ContextEndLogId], [InputIsTruncated] AS [InputIsTruncated], CONVERT(varbinary(max),[EvidenceLevel]) AS [EvidenceLevel], CONVERT(varbinary(max),[EvidenceSource]) AS [EvidenceSource], CONVERT(varbinary(max),[MessageText]) AS [MessageText] FROM #ExampleBeginExpected EXCEPT SELECT [PipelinePhaseBeginEventOrdinal] AS [PipelinePhaseBeginEventOrdinal], [LogId] AS [LogId], [ExecutionId] AS [ExecutionId], CONVERT(varbinary(max),[EventName]) AS [EventName], [SourceId] AS [SourceId], CONVERT(varbinary(max),[SourceName]) AS [SourceName], [EventTime] AS [EventTime], [DataCode] AS [DataCode], CONVERT(varbinary(max),[ParserId]) AS [ParserId], CONVERT(varbinary(max),[ParseStatus]) AS [ParseStatus], CONVERT(varbinary(max),[ObservationKind]) AS [ObservationKind], CONVERT(varbinary(max),[PhaseName]) AS [PhaseName], CONVERT(varbinary(max),[ContextStatus]) AS [ContextStatus], [ContextStartLogId] AS [ContextStartLogId], [ContextEndLogId] AS [ContextEndLogId], [InputIsTruncated] AS [InputIsTruncated], CONVERT(varbinary(max),[EvidenceLevel]) AS [EvidenceLevel], CONVERT(varbinary(max),[EvidenceSource]) AS [EvidenceSource], CONVERT(varbinary(max),[MessageText]) AS [MessageText] FROM #ExampleBeginExport) AND (SELECT COUNT(*) FROM #ExampleBeginExport)=(SELECT COUNT(*) FROM #ExampleBeginExpected) THEN 1 ELSE 0 END;',N'@Ok bit OUTPUT',@Ok=@ExportMatches OUTPUT;
    IF @ExportMatches<>1 THROW 57107,N'PB_TABLE_VALUES',1;
    CREATE TABLE #ExampleBeginSchema(Ordinal int,Name sysname,TypeName sysname,MaxLength smallint,Prec tinyint,Scale tinyint,Nullable bit,CollationName sysname NULL);
    INSERT #ExampleBeginSchema VALUES
