(19,N'MessageText',N'nvarchar',-1,0,0,1,N'SQL_Latin1_General_CP1_CS_AS');
    IF EXISTS(SELECT * FROM #ExampleBeginSchema EXCEPT SELECT CONVERT(int,ROW_NUMBER() OVER(ORDER BY c.column_id)),c.name,t.name,c.max_length,c.precision,c.scale,c.is_nullable,c.collation_name FROM tempdb.sys.columns c JOIN tempdb.sys.types t ON t.user_type_id=c.user_type_id WHERE c.object_id=OBJECT_ID(N'tempdb..#ExampleBeginExport')) OR (SELECT COUNT(*) FROM tempdb.sys.columns WHERE object_id=OBJECT_ID(N'tempdb..#ExampleBeginExport'))<>19 OR EXISTS(SELECT 1 FROM tempdb.sys.columns WHERE object_id=OBJECT_ID(N'tempdb..#ExampleBeginExport') AND (is_identity=1 OR is_computed=1)) THROW 57108,N'PB_TABLE_NATIVE_SCHEMA',1;
    DECLARE @MapCase int=1,@Map nvarchar(max),@Caught int;
