            EXEC [monitor].[USP_SsisLegacyLogAnalysis] @LoggingDatabase=@Db,@ExecutionId=@Id,@HighImpactConfirmed=1,@IncludePipelinePhaseBeginAnalysis=@Begin,@ResultSetArt='TABLE',@ResultTablesJson=@Map,@PrintMeldungen=0;
