    EXEC [monitor].[USP_SsisLegacyLogAnalysis] @LoggingDatabase=@Db,@LoggingTable=N'ExamplePipelinePhaseBeginLogSource',@ExecutionId=@Id,@HighImpactConfirmed=0,@IncludePipelinePhaseBeginAnalysis=1,
        @ResultSetArt='NONE',@JsonErzeugen=1,@Json=@J OUTPUT,@PrintMeldungen=0,@StatusCodeOut=@Status OUTPUT;
    IF @Status<>'INVALID_PARAMETER' OR ISNULL(JSON_QUERY(@J,'$.pipelinePhaseBeginEvents'),N'MISSING')<>N'[]' THROW 57114,N'PB_HIGH_IMPACT_GATE',1;
    EXEC [monitor].[USP_SsisLegacyLogAnalysis] @LoggingDatabase=@Db,@LoggingTable=N'ExamplePipelinePhaseBeginLogSource',@ExecutionId=@Id,@HighImpactConfirmed=1,@IncludePipelinePhaseBeginAnalysis=1,@IncludeMessages=0,
        @ResultSetArt='NONE',@JsonErzeugen=1,@Json=@J OUTPUT,@PrintMeldungen=0;
    IF ISNULL(JSON_QUERY(@J,'$.pipelinePhaseBeginEvents'),N'MISSING')<>N'[]' OR NOT EXISTS(SELECT 1 FROM OPENJSON(@J,'$.sourceStatus') WHERE JSON_VALUE(value,'$.SourceName')=N'pipelinePhaseBeginAnalysis' AND JSON_VALUE(value,'$.Detail')=N'MESSAGES_DISABLED' AND JSON_VALUE(value,'$.ObservedRowCount') IS NULL) THROW 57109,N'PB_MESSAGES_DISABLED',1;
    EXEC [monitor].[USP_SsisLegacyLogAnalysis] @LoggingDatabase=@Db,@LoggingTable=N'ExamplePipelinePhaseBeginMissing',@ExecutionId=@Id,@HighImpactConfirmed=1,@IncludePipelinePhaseBeginAnalysis=1,
        @ResultSetArt='NONE',@JsonErzeugen=1,@Json=@J OUTPUT,@PrintMeldungen=0;
    IF ISNULL(JSON_QUERY(@J,'$.pipelinePhaseBeginEvents'),N'MISSING')<>N'[]' OR NOT EXISTS(SELECT 1 FROM OPENJSON(@J,'$.sourceStatus') WHERE JSON_VALUE(value,'$.SourceName')=N'pipelinePhaseBeginAnalysis' AND JSON_VALUE(value,'$.Detail')=N'NO_VALID_EVENT_BUFFER') THROW 57110,N'PB_MISSING_SOURCE',1;
    ALTER TABLE dbo.ExamplePipelinePhaseBeginLogSource DROP COLUMN event;
    EXEC [monitor].[USP_SsisLegacyLogAnalysis] @LoggingDatabase=@Db,@LoggingTable=N'ExamplePipelinePhaseBeginLogSource',@ExecutionId=@Id,@HighImpactConfirmed=1,@IncludePipelinePhaseBeginAnalysis=1,
        @ResultSetArt='NONE',@JsonErzeugen=1,@Json=@J OUTPUT,@PrintMeldungen=0;
    IF ISNULL(JSON_QUERY(@J,'$.pipelinePhaseBeginEvents'),N'MISSING')<>N'[]' THROW 57111,N'PB_REQUIRED_COLUMN',1;
    ALTER TABLE dbo.ExamplePipelinePhaseBeginLogSource ADD event nvarchar(128) COLLATE SQL_Latin1_General_CP1_CS_AS NULL;
    UPDATE dbo.ExamplePipelinePhaseBeginLogSource SET event=CASE id WHEN 10 THEN N'OnPreExecute' WHEN 20 THEN N'OnInformation' ELSE N'OnPostExecute' END;
    CREATE USER ExamplePipelinePhaseBeginReader WITHOUT LOGIN;
    SET @UserId=DATABASE_PRINCIPAL_ID(N'ExamplePipelinePhaseBeginReader');
    GRANT EXECUTE ON SCHEMA::monitor TO ExamplePipelinePhaseBeginReader;
    GRANT VIEW DEFINITION ON dbo.ExamplePipelinePhaseBeginLogSource TO ExamplePipelinePhaseBeginReader;
    DENY SELECT ON dbo.ExamplePipelinePhaseBeginLogSource TO ExamplePipelinePhaseBeginReader;
    DECLARE @DirectError int,@DirectMessage nvarchar(4000);
    BEGIN TRY
        EXECUTE AS USER='ExamplePipelinePhaseBeginReader';SET @Impersonated=1;
        BEGIN TRY EXEC sys.sp_executesql N'SELECT id FROM dbo.ExamplePipelinePhaseBeginLogSource;';END TRY BEGIN CATCH SELECT @DirectError=ERROR_NUMBER(),@DirectMessage=ERROR_MESSAGE();END CATCH;
        EXEC [monitor].[USP_SsisLegacyLogAnalysis] @LoggingDatabase=@Db,@LoggingTable=N'ExamplePipelinePhaseBeginLogSource',@ExecutionId=@Id,@HighImpactConfirmed=1,@IncludePipelinePhaseBeginAnalysis=1,
            @ResultSetArt='NONE',@JsonErzeugen=1,@Json=@J OUTPUT,@PrintMeldungen=0,@ErrorNumberOut=@Error OUTPUT,@ErrorMessageOut=@Message OUTPUT;
        REVERT;SET @Impersonated=0;
    END TRY BEGIN CATCH IF @Impersonated=1 BEGIN REVERT;SET @Impersonated=0;END;THROW;END CATCH;
    IF ISNULL(@DirectError,0)<>229 OR ISNULL(@Error,0)<>229 OR @Message IS NULL OR @DirectMessage IS NULL
        OR CONVERT(varbinary(max),@Message)<>CONVERT(varbinary(max),@DirectMessage) OR ISNULL(JSON_QUERY(@J,'$.pipelinePhaseBeginEvents'),N'MISSING')<>N'[]' THROW 57112,N'PB_NATIVE_DENIAL',1;
    IF DATABASE_PRINCIPAL_ID(N'ExamplePipelinePhaseBeginReader')<>@UserId THROW 57191,N'PB_USER_ID_CHANGED',1;
    DROP USER ExamplePipelinePhaseBeginReader;SET @UserId=NULL;
    IF OBJECT_ID(N'dbo.ExamplePipelinePhaseBeginLogSource')<>@TableId THROW 57192,N'PB_TABLE_ID_CHANGED',1;
    DROP TABLE dbo.ExamplePipelinePhaseBeginLogSource;SET @TableId=NULL;
    IF @@OPTIONS<>@OuterOptions OR @@LOCK_TIMEOUT<>@OuterLock OR @@TRANCOUNT<>@OuterTran THROW 57113,N'PB_CALLER_CHANGED',1;
    SELECT N'PASS' AS PipelinePhaseBeginSyntheticStatus,28 AS PayloadAndContextCases,256 AS FlagCases,6 AS MappingCases,5 AS SourceCases,19 AS IndependentFields;
END TRY
BEGIN CATCH
    IF @Impersonated=1 REVERT;
    IF @UserId IS NOT NULL AND DATABASE_PRINCIPAL_ID(N'ExamplePipelinePhaseBeginReader')=@UserId DROP USER ExamplePipelinePhaseBeginReader;
    IF @TableId IS NOT NULL AND OBJECT_ID(N'dbo.ExamplePipelinePhaseBeginLogSource')=@TableId DROP TABLE dbo.ExamplePipelinePhaseBeginLogSource;
    THROW;
END CATCH;
GO
